/**
 * Networks and stations as mitren.app names them.
 *
 * The search API that would answer this at runtime sends no CORS header, so
 * the names are baked in: stations.data.json is generated by
 * tools/build_stations.py from the data dondeestamitren itself ships
 * (Apache-2.0).
 *
 * mitren.app's socket is per network, so a code travels with its network, and
 * a network with its *feed*: the three sets of networks the site offers, one
 * per operator. Renfe's codes are the five-digit ones ADIF uses; Euskotren's
 * and Metro Bilbao's are their own, and only mean anything inside their feed.
 */
import type { Place } from '../../model';
import data from './stations.data.json';

export interface Network {
  id: string;
  name: string;
  /** The city slug of the network's pages on mitren.app. */
  city: string;
  /** The mode slug of those pages: `cercanias`, `suburbano`, `tranvia`, `metro`. */
  mode: string;
  /** Which feed it belongs to. */
  feed: string;
}

export interface Station {
  network: string;
  networkName: string;
  /** The feed of its network, copied here so a search can filter on it. */
  feed: string;
  code: string;
  name: string;
  /** Shorter forms, '' when mitren.app has none. */
  short: string;
  mini: string;
  town: string;
  aliases: string[];
  /** Everything a search may match on, folded. */
  haystack: string;
  foldedName: string;
}

/** Which commit of dondeestamitren the list was built from. */
export const STATIONS_SOURCE: string = data.source;

export const NETWORKS: Network[] = data.networks;

/** The feeds the source offers, in the order it lists them. */
export const FEEDS = ['cercanias', 'euskotren', 'metro-bilbao'] as const;

export type Feed = (typeof FEEDS)[number];

/** What an embed that names no feed means: the only one the source had at first. */
export const DEFAULT_FEED: Feed = 'cercanias';

/** Where a bare station code is looked for first, per feed. */
const DEFAULT_NETWORKS: Record<string, string> = {
  cercanias: 'madrid_cercanias',
  euskotren: 'bilbao_euskotren',
  'metro-bilbao': 'bilbao_metro',
};

/**
 * The scheme a feed's station codes belong to. Renfe's are ADIF's own
 * register; the other two are the operator's own numbering.
 */
const CODE_SCHEMES: Record<string, string> = {
  cercanias: 'adif',
  euskotren: 'euskotren',
  'metro-bilbao': 'metro-bilbao',
};

export const TIME_ZONE = 'Europe/Madrid';

export function isFeed(value: string | undefined | null): value is Feed {
  return (FEEDS as readonly string[]).includes(String(value ?? ''));
}

/** The feed a network belongs to; the default feed when the network is not listed. */
export function feedOf(network: string): Feed {
  const feed = getIndex().networkById.get(String(network).trim())?.feed;
  return isFeed(feed) ? feed : DEFAULT_FEED;
}

/** Where a bare code of this feed is looked for first. */
export function defaultNetwork(feed: string | undefined): string {
  return DEFAULT_NETWORKS[String(feed ?? '')] ?? DEFAULT_NETWORKS[DEFAULT_FEED]!;
}

export function networksOf(feed: string): Network[] {
  return NETWORKS.filter((network) => network.feed === feed);
}

/** The scheme to file a station code of this feed under. */
export function codeScheme(feed: string | undefined): string {
  return CODE_SCHEMES[String(feed ?? '')] ?? CODE_SCHEMES[DEFAULT_FEED]!;
}

/**
 * Case- and accent-insensitive form for matching. "Ñ" folds to "N" here,
 * which is what someone typing on a keyboard without one expects.
 */
export function fold(text: string | undefined | null): string {
  return String(text ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

interface Index {
  stations: Station[];
  byKey: Map<string, Station>;
  networkById: Map<string, Network>;
  /** A station by any spelling of its name, per feed. The first to claim a spelling keeps it. */
  byName: Map<string, Station>;
}

let index: Index | undefined;

/** Built on first use rather than on import: a thousand rows nobody may ask about. */
function getIndex(): Index {
  if (index) return index;
  const networkById = new Map(NETWORKS.map((network) => [network.id, network]));
  const stations = (data.stations as string[][]).map((row): Station => {
    const [network = '', code = '', name = '', short = '', mini = '', town = '', aliases = ''] = row;
    const list = aliases ? aliases.split('|') : [];
    return {
      network,
      networkName: networkById.get(network)?.name ?? network,
      feed: networkById.get(network)?.feed ?? DEFAULT_FEED,
      code,
      name,
      short,
      mini,
      town,
      aliases: list,
      haystack: fold([name, short, mini, town, ...list].join(' ')),
      foldedName: fold(name),
    };
  });
  const byName = new Map<string, Station>();
  for (const station of stations) {
    for (const form of [station.name, station.short, station.mini]) {
      const key = fold(form);
      // Names are only ever looked up within one feed: two operators may well
      // serve a place of the same name, and each means its own station.
      if (key && !byName.has(`${station.feed}/${key}`)) byName.set(`${station.feed}/${key}`, station);
    }
  }
  index = {
    stations,
    byKey: new Map(stations.map((station) => [`${station.network}/${station.code}`, station])),
    networkById,
    byName,
  };
  return index;
}

export function allStations(): Station[] {
  return getIndex().stations;
}

export function findNetwork(id: string): Network | undefined {
  return getIndex().networkById.get(String(id).trim());
}

export function networkName(id: string): string {
  return getIndex().networkById.get(id)?.name ?? id;
}

export function findStation(network: string, code: string): Station | undefined {
  return getIndex().byKey.get(`${network}/${String(code).trim()}`);
}

/**
 * A code on its own, within one feed. Most codes belong to one network; where
 * one is shared (a guest line), the feed's default network wins, then the
 * first listed.
 */
export function networkForCode(code: string, feed?: string): string | undefined {
  const wanted = String(code).trim();
  const within = feed ?? DEFAULT_FEED;
  const matches = getIndex().stations.filter((station) => station.code === wanted && (!feed || station.feed === feed));
  if (matches.length === 0) return undefined;
  const preferred = defaultNetwork(within);
  return (matches.find((station) => station.network === preferred) ?? matches[0]!).network;
}

/**
 * A station by any spelling of its name, within the feed of `network`.
 * `network` wins when several of its feed share the spelling.
 */
export function findStationByName(name: string, network?: string): Station | undefined {
  const key = fold(name);
  if (!key) return undefined;
  const feed = network ? feedOf(network) : DEFAULT_FEED;
  if (network) {
    const local = getIndex().stations.find(
      (station) => station.network === network && [station.name, station.short, station.mini].some((form) => fold(form) === key),
    );
    if (local) return local;
  }
  return getIndex().byName.get(`${feed}/${key}`);
}

/** A station's own spellings of its name, longest first. */
export function stationLadder(station: Station): string[] {
  return [station.name, station.short, station.mini].filter(Boolean);
}

/**
 * Every spelling of the station called `name`, longest first; just `name`
 * when the list does not know it. A departure names its destination in full,
 * and a narrow sign picks the longest form that fits.
 */
export function nameLadder(name: string, network?: string): string[] {
  const station = findStationByName(name, network);
  return station ? stationLadder(station) : [String(name ?? '')];
}

/** A station as a model Place, with its name ladder. */
export function stationPlace(station: Station): Place {
  const [name = station.name, ...names] = stationLadder(station);
  const place: Place = {
    id: `${station.network}/${station.code}`,
    codes: { [codeScheme(station.feed)]: station.code },
    name,
    country: 'es',
    timeZone: TIME_ZONE,
  };
  if (names.length) place.names = names;
  if (station.town) place.town = station.town;
  return place;
}

/** A place for a name off the feed: the listed station when it resolves, else the bare name. */
export function placeForName(name: string, network?: string): Place {
  const station = findStationByName(name, network);
  return station ? stationPlace(station) : { name: String(name), country: 'es', timeZone: TIME_ZONE };
}

/**
 * Ranked matches for what someone typed: a station code, or words from the
 * name, its short forms, its town or mitren.app's search aliases, in any
 * order and without accents. `feed` keeps the search inside one operator's
 * networks, and `network` floats that network's matches up.
 */
export function searchStations(query: string, options: { feed?: string; network?: string; limit?: number } = {}): Station[] {
  const prefer = options.network;
  const limit = options.limit ?? 8;
  const q = fold(query);
  if (!q) return [];
  const words = q.split(' ');
  const first = words[0] ?? '';
  const numeric = /^\d+$/.test(q);
  const scored: [number, Station][] = [];
  for (const station of getIndex().stations) {
    if (options.feed && station.feed !== options.feed) continue;
    let score: number;
    if (numeric) {
      if (!station.code.startsWith(q)) continue;
      score = station.code === q ? 0 : 1;
    } else {
      if (!words.every((word) => station.haystack.includes(word))) continue;
      if (station.foldedName.startsWith(q)) score = 0;
      else if (` ${station.foldedName}`.includes(` ${first}`)) score = 1;
      else if (station.foldedName.includes(first)) score = 2;
      else score = 3; // matched on town or alias only
    }
    if (prefer && station.network !== prefer) score += 0.5;
    scored.push([score, station]);
  }
  scored.sort((a, b) => a[0] - b[0] || a[1].name.localeCompare(b[1].name, 'es'));
  return scored.slice(0, limit).map(([, station]) => station);
}

/**
 * The station's page on mitren.app. The city/mode form is the public one;
 * mitren.app redirects it to its canonical slug where those differ.
 */
export function stationUrl(network: string, code: string): string {
  const net = getIndex().networkById.get(network);
  if (!net || !/^\d+$/.test(String(code))) return 'https://mitren.app/';
  return `https://mitren.app/${encodeURIComponent(net.city)}/${encodeURIComponent(net.mode)}/stations/${encodeURIComponent(code)}`;
}
